add_action( 'admin_menu', 'perfectpixel_orders_top_level_menu', 99 );

function perfectpixel_orders_top_level_menu() {
	if ( ! current_user_can( 'edit_shop_orders' ) ) {
		return;
	}
	$hpos = class_exists( '\Automattic\WooCommerce\Utilities\OrderUtil' ) && \Automattic\WooCommerce\Utilities\OrderUtil::custom_orders_table_usage_is_enabled();
	$url  = $hpos ? 'admin.php?page=wc-orders' : 'edit.php?post_type=shop_order';
	$count = function_exists( 'wc_orders_count' ) ? (int) wc_orders_count( 'processing' ) : 0;
	$title = __( 'Orders', 'woocommerce' ) . ( $count ? ' <span class="awaiting-mod count-' . $count . '"><span class="processing-count">' . number_format_i18n( $count ) . '</span></span>' : '' );
	add_menu_page( __( 'Orders', 'woocommerce' ), $title, 'edit_shop_orders', $url, '', 'dashicons-cart', (float) '{{orders_menu_position}}' );
}
